#!/usr/bin/env bash
set -euo pipefail

# TSP_FOG_NO_PBO_V1
#
# VM-side one-shot builder/installer.
# - Backs up the relevant OpenMW source and current build output first.
# - Adds an environment-gated fog-of-war no-PBO path.
# - Incrementally builds ONLY the openmw target.
# - Installs the result beside the production OpenMW binary.
# - Installs a new V9 diagnostic launcher beside existing launchers.
# - Never overwrites bin/openmw-0.51 or lib/libGL.so.1.
# - V9 selects the sidecar ONLY on original TSP / PowerVR.
#
# Override the device address if necessary:
#   ./apply_TSP_FOG_NO_PBO_V1_PRECHECK.sh root@192.168.1.21
# or:
#   TSP_HOST=root@192.168.1.21 ./apply_TSP_FOG_NO_PBO_V1_PRECHECK.sh

HOST="${1:-${TSP_HOST:-root@192.168.1.21}}"
CONTAINER="openmw_builder"
SRC="/root/openmw-0.51-tsp-src"
BUILD="/root/openmw-0.51-tsp-build"
CPP="$SRC/apps/openmw/mwrender/localmap.cpp"

DL="$HOME/Downloads"
mkdir -p "$DL"

STAMP="$(date +%Y%m%d-%H%M%S)"
LOCAL_BIN="$DL/openmw-0.51.tsp-fog-nopbo-v1"
LOCAL_LAUNCHER="$DL/Morrowind-TSP-FOG-NOPBO-DIAG-V9.sh"
SOCK="/tmp/tsp-fog-nopbo-$$"

cleanup() {
    if [ -S "$SOCK" ] || [ -e "$SOCK" ]; then
        ssh -S "$SOCK" -O exit "$HOST" >/dev/null 2>&1 || true
    fi
}
trap cleanup EXIT

echo "============================================================"
echo "TSP_FOG_NO_PBO_V1"
echo "============================================================"
echo "Container: $CONTAINER"
echo "Source:    $CPP"
echo "Device:    $HOST"
echo

echo "[0/8] DEVICE NETWORK + AUTHENTICATION PRECHECK"
echo "This happens BEFORE any backup, patch, or build."
echo "If this VM needs a password, enter it now; it should not ask again."
echo

# Open the persistent SSH master FIRST.  ControlPersist=yes keeps the
# authenticated connection alive for the whole build until cleanup() closes it.
if ! ssh -M -S "$SOCK" \
    -o ControlMaster=yes \
    -o ControlPersist=yes \
    -o ConnectTimeout=5 \
    "$HOST" true
then
    RC=$?
    echo
    echo "============================================================"
    echo "PRECHECK FAILED -- NOTHING WAS BUILT OR MODIFIED THIS RUN"
    echo "============================================================"
    echo "Target: $HOST"
    echo
    echo "Important: 'Network is unreachable' is NOT an Internet failure."
    echo "It means this VM currently has no route to that TSP LAN address,"
    echo "or the TSP's LAN IP has changed."
    echo
    echo "From your already-authenticated LobiShell session on the TSP, run:"
    echo "  ip -4 -o addr show scope global"
    echo
    echo "Then rerun this installer with the current address, for example:"
    echo "  ./apply_TSP_FOG_NO_PBO_V1_PRECHECK.sh root@192.168.1.37"
    echo
    echo "VM route information:"
    ip -4 route 2>/dev/null || true
    echo
    echo "No source/build/device changes were made by this failed run."
    exit "${RC:-1}"
fi

echo
echo "SSH PRECHECK: PASS"
echo "Persistent authenticated connection is open."
echo

command -v docker >/dev/null 2>&1 || {
    echo "ERROR: docker is not available"
    exit 10
}

docker inspect "$CONTAINER" >/dev/null 2>&1 || {
    echo "ERROR: Docker container not found: $CONTAINER"
    exit 11
}

echo "[1/8] Backing up relevant source and current build output..."

docker exec -i "$CONTAINER" bash -s -- "$STAMP" <<'DOCKER'
set -euo pipefail
STAMP="$1"
SRC="/root/openmw-0.51-tsp-src"
BUILD="/root/openmw-0.51-tsp-build"
CPP="$SRC/apps/openmw/mwrender/localmap.cpp"
BACK="/root/tsp_patch_backups/fog-nopbo-v1-$STAMP"

mkdir -p "$BACK"

[ -f "$CPP" ] || {
    echo "ERROR: missing $CPP"
    exit 20
}

cp -p "$CPP" "$BACK/localmap.cpp.before"

for b in "$BUILD/openmw" "$BUILD/apps/openmw/openmw"; do
    if [ -f "$b" ]; then
        cp -p "$b" "$BACK/$(basename "$b").before"
        sha256sum "$b" > "$BACK/openmw-build.before.sha256"
        echo "$b" > "$BACK/openmw-build.path"
        break
    fi
done

git -C "$SRC" status --short > "$BACK/git-status.before.txt" 2>&1 || true
git -C "$SRC" diff -- apps/openmw/mwrender/localmap.cpp \
    > "$BACK/localmap.before.diff" 2>&1 || true

sha256sum "$CPP" > "$BACK/localmap.cpp.before.sha256"

echo "backup=$BACK"
DOCKER

echo "[2/8] Applying the environment-gated fog PBO bypass..."

docker exec -i "$CONTAINER" python3 - <<'PY'
from pathlib import Path

p = Path("/root/openmw-0.51-tsp-src/apps/openmw/mwrender/localmap.cpp")
s = p.read_text()

marker = "TSP_FOG_NO_PBO_V1"

if marker not in s:
    old = '''        mFogOfWarImage = new osg::Image;
        // Assign a PixelBufferObject for asynchronous transfer of data to the GPU
        mFogOfWarImage->setPixelBufferObject(new osg::PixelBufferObject);
        mFogOfWarImage->allocateImage(sFogOfWarResolution, sFogOfWarResolution, 1, GL_RGBA, GL_UNSIGNED_BYTE);
'''

    new = '''        mFogOfWarImage = new osg::Image;
        // TSP_FOG_NO_PBO_V1
        //
        // Original TSP / PowerVR A/B. OSG normally gives this tiny, frequently
        // dirtied fog-of-war image a PixelBufferObject. gl4es must emulate that
        // unpack-PBO path, and the local map + compass are the two consumers that
        // corrupt together on the PowerVR unit. When the launcher exports
        // TSP_FOG_NO_PBO=1, upload this image directly instead.
        //
        // TSPS/Mali and every normal launcher keep the upstream PBO path.
        const bool tspFogNoPbo = (std::getenv("TSP_FOG_NO_PBO") != nullptr);
        if (!tspFogNoPbo)
            mFogOfWarImage->setPixelBufferObject(new osg::PixelBufferObject);

        static bool tspFogNoPboLogged = false;
        if (!tspFogNoPboLogged)
        {
            tspFogNoPboLogged = true;
            Log(Debug::Info) << "TSP_FOG_NO_PBO_V1 active=" << (tspFogNoPbo ? 1 : 0)
                             << " pbo=" << (tspFogNoPbo ? 0 : 1)
                             << " size=" << sFogOfWarResolution << "x" << sFogOfWarResolution;
        }

        mFogOfWarImage->allocateImage(sFogOfWarResolution, sFogOfWarResolution, 1, GL_RGBA, GL_UNSIGNED_BYTE);
'''

    c = s.count(old)
    if c != 1:
        raise SystemExit(f"ERROR: expected exactly one fog PBO anchor; found {c}")

    s = s.replace(old, new, 1)
    p.write_text(s)

s = p.read_text()
if s.count("TSP_FOG_NO_PBO_V1") != 2:
    raise SystemExit(
        "ERROR: unexpected TSP_FOG_NO_PBO_V1 marker count=%d"
        % s.count("TSP_FOG_NO_PBO_V1")
    )
if s.count('std::getenv("TSP_FOG_NO_PBO")') != 1:
    raise SystemExit("ERROR: TSP_FOG_NO_PBO env gate count is not 1")

print("PASS: source patch present exactly once")
PY

echo "[3/8] Committing ONLY the patched localmap.cpp before build..."

docker exec "$CONTAINER" bash -c '
set -e
cd /root/openmw-0.51-tsp-src
git add -- apps/openmw/mwrender/localmap.cpp
if git diff --cached --quiet -- apps/openmw/mwrender/localmap.cpp; then
    echo "Nothing new to commit (patch was already present)."
else
    git commit -q -m "TSP_FOG_NO_PBO_V1: PowerVR fog upload A/B"
    echo "Committed TSP_FOG_NO_PBO_V1."
fi
'

echo "[4/8] Incrementally building openmw (-j2)..."

docker exec "$CONTAINER" \
    cmake --build "$BUILD" --target openmw -- -j2

BUILT="$(
    docker exec "$CONTAINER" sh -c '
        for b in \
            /root/openmw-0.51-tsp-build/openmw \
            /root/openmw-0.51-tsp-build/apps/openmw/openmw
        do
            [ -x "$b" ] && { printf "%s\n" "$b"; exit 0; }
        done
        exit 1
    '
)"

[ -n "$BUILT" ] || {
    echo "ERROR: could not locate built OpenMW binary"
    exit 30
}

echo "Built binary: $BUILT"

docker cp "$CONTAINER:$BUILT" "$LOCAL_BIN"
chmod 0755 "$LOCAL_BIN"

MARKERS="$(grep -a -c 'TSP_FOG_NO_PBO_V1 active=' "$LOCAL_BIN" 2>/dev/null || true)"
[ "$MARKERS" -ge 1 ] || {
    echo "ERROR: built binary does not contain TSP_FOG_NO_PBO_V1 log marker"
    exit 31
}

BIN_SHA="$(sha256sum "$LOCAL_BIN" | awk '{print $1}')"

echo "Sidecar SHA256: $BIN_SHA"

echo "[5/8] Emitting the dedicated V9 launcher..."

base64 -d > "$LOCAL_LAUNCHER" <<'V9_B64'

V9_B64

chmod 0755 "$LOCAL_LAUNCHER"

LAUNCHER_SHA="$(sha256sum "$LOCAL_LAUNCHER" | awk '{print $1}')"
EXPECTED_LAUNCHER_SHA="34aed7cad96aad21b81ee044d95ba9ddacf31144813e57ae0cf626bf9c982577"

[ "$LAUNCHER_SHA" = "$EXPECTED_LAUNCHER_SHA" ] || {
    echo "ERROR: embedded V9 launcher hash mismatch"
    echo "actual=$LAUNCHER_SHA"
    echo "expected=$EXPECTED_LAUNCHER_SHA"
    exit 32
}

sh -n "$LOCAL_LAUNCHER"
bash -n "$LOCAL_LAUNCHER"

echo "[6/8] Reusing the authenticated SSH connection opened at startup..."

if ! ssh -S "$SOCK" -o BatchMode=yes "$HOST" true; then
    echo "ERROR: the authenticated SSH master connection was lost during the build."
    echo "No device files have been installed by this run."
    exit 33
fi

echo "SSH connection: PASS"

echo "[7/8] Copying sidecar binary and launcher to temporary device paths..."

scp -q -o ControlPath="$SOCK" \
    "$LOCAL_BIN" \
    "$HOST:/tmp/openmw-0.51.tsp-fog-nopbo-v1"

scp -q -o ControlPath="$SOCK" \
    "$LOCAL_LAUNCHER" \
    "$HOST:/tmp/Morrowind-TSP-FOG-NOPBO-DIAG-V9.sh"

echo "[8/8] Installing ALONGSIDE production files and verifying they stay unchanged..."

ssh -S "$SOCK" "$HOST" 'sh -s' <<'REMOTE'
set -e

ROOT=""
for r in \
    /mnt/mmc/ports/openmw \
    /mnt/SDCARD/data/ports/openmw \
    /userdata/roms/ports/openmw \
    /roms/ports/openmw \
    /storage/roms/ports/openmw
do
    [ -x "$r/bin/openmw-0.51" ] && { ROOT="$r"; break; }
done

[ -n "$ROOT" ] || {
    echo "ERROR: OpenMW root not found"
    exit 40
}

PORTS=""
for p in \
    /mnt/mmc/ROMS/Ports \
    /mnt/SDCARD/ROMS/Ports \
    /userdata/roms/ports \
    /roms/ports \
    /storage/roms/ports
do
    [ -d "$p" ] && { PORTS="$p"; break; }
done

[ -n "$PORTS" ] || {
    echo "ERROR: Ports launcher directory not found"
    exit 41
}

PROD_BIN="$ROOT/bin/openmw-0.51"
PROD_GL="$ROOT/lib/libGL.so.1"
SIDE_BIN="$ROOT/bin/openmw-0.51.tsp-fog-nopbo-v1"
LAUNCHER="$PORTS/Morrowind-TSP-FOG-NOPBO-DIAG-V9.sh"

PROD_BIN_SHA_BEFORE="$(sha256sum "$PROD_BIN" | awk '{print $1}')"
PROD_GL_SHA_BEFORE="$(sha256sum "$PROD_GL" | awk '{print $1}')"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACK="$ROOT/tsp_patch_backups/fog-nopbo-device-$STAMP"
mkdir -p "$BACK"

[ -f "$SIDE_BIN" ] && cp -p "$SIDE_BIN" "$BACK/openmw-sidecar.before" || true
[ -f "$LAUNCHER" ] && cp -p "$LAUNCHER" "$BACK/launcher.before" || true

install -m 0755 /tmp/openmw-0.51.tsp-fog-nopbo-v1 "$SIDE_BIN"
install -m 0755 /tmp/Morrowind-TSP-FOG-NOPBO-DIAG-V9.sh "$LAUNCHER"

rm -f \
    /tmp/openmw-0.51.tsp-fog-nopbo-v1 \
    /tmp/Morrowind-TSP-FOG-NOPBO-DIAG-V9.sh

PROD_BIN_SHA_AFTER="$(sha256sum "$PROD_BIN" | awk '{print $1}')"
PROD_GL_SHA_AFTER="$(sha256sum "$PROD_GL" | awk '{print $1}')"

[ "$PROD_BIN_SHA_BEFORE" = "$PROD_BIN_SHA_AFTER" ] || {
    echo "ERROR: production OpenMW changed unexpectedly"
    exit 42
}

[ "$PROD_GL_SHA_BEFORE" = "$PROD_GL_SHA_AFTER" ] || {
    echo "ERROR: production libGL changed unexpectedly"
    exit 43
}

echo
echo "============================================================"
echo "TSP_FOG_NO_PBO_V1 INSTALLED"
echo "============================================================"
echo "Production OpenMW UNCHANGED:"
sha256sum "$PROD_BIN"
echo
echo "Production libGL UNCHANGED:"
sha256sum "$PROD_GL"
echo
echo "Added TSP-only sidecar:"
sha256sum "$SIDE_BIN"
echo
echo "Added launcher:"
sha256sum "$LAUNCHER"
echo
echo "Launcher to run:"
echo "$LAUNCHER"
echo
echo "Device backup:"
echo "$BACK"
REMOTE

echo
echo "============================================================"
echo "DONE"
echo "============================================================"
echo "VM sidecar copy:"
echo "  $LOCAL_BIN"
echo "  SHA256 $BIN_SHA"
echo
echo "VM launcher copy:"
echo "  $LOCAL_LAUNCHER"
echo "  SHA256 $LAUNCHER_SHA"
echo
echo "On the TSP, launch:"
echo "  Morrowind-TSP-FOG-NOPBO-DIAG-V9.sh"
echo
echo "Expected OpenMW log proof:"
echo "  TSP_FOG_NO_PBO_LAUNCH_V1 selected=1"
echo "  TSP_FOG_NO_PBO_V1 active=1 pbo=0"
